const input = items[0]?.json ?? {};
const body = input.body ?? input;
const type = String(body.type ?? '').trim();
const schemaVersion = String(body.schemaVersion ?? '').trim();
const requestId = String(body.requestId ?? '').trim();
const now = new Date().toISOString();
const allowedGoals = new Set(['jobs','projects','startups','companies','events','community','exploring']);
const allowedStatus = new Set(['bachelor','master','research','professional','founder','other']);
const allowedStudy = new Set(['computer-science','ai-data','engineering','business-informatics','business','entrepreneurship','product-design','media','science-research','other','unsure']);
const allowedExperience = new Set(['none','uni-projects','first-role','multiple']);
const allowedContribution = new Set(['tech','data','product','business','entrepreneurship','community','unsure']);
const allowedPatchKeys = new Set(['selectedGoals','status','studyField','studyFieldOther','university','experienceLevel','contributionAreas','linkedinUrl','githubUrl','portfolioUrl']);
function clean(v,max=500){ return String(v ?? '').trim().slice(0,max); }
function list(v,set,maxItems){ return Array.isArray(v) ? [...new Set(v.map(x=>clean(x,80)).filter(x=>set.has(x)))].slice(0,maxItems) : []; }
function validEmail(v){ return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v); }
let valid = schemaVersion === 'community-v1' && requestId.length >= 8;
let error = '';
let normalized = { type, schemaVersion, requestId, receivedAtN8n: now };
if (type === 'community_join') {
  const p = body.payload ?? {};
  const firstName = clean(p.firstName,120);
  const lastName = clean(p.lastName,120);
  const email = clean(p.email,254);
  const emailNormalized = email.toLowerCase();
  const selectedGoals = list(p.selectedGoals, allowedGoals, 3);
  const language = p.language === 'en' ? 'en' : 'de';
  const consent = p.consent === true;
  if (!firstName || !lastName || !validEmail(email) || !consent) { valid = false; error = 'Missing or invalid required join fields'; }
  const a = p.attribution ?? {};
  normalized = {
    ...normalized, valid, error, firstName, lastName, fullName: `${firstName} ${lastName}`.trim(), email, emailNormalized,
    selectedGoals, language, consent, consentedAt: clean(p.consentedAt,80) || now,
    consentVersion: clean(p.consentVersion,120) || 'community-updates-v1', createdAt: clean(p.createdAt,80) || now,
    utmSource: clean(a.utmSource,200), utmMedium: clean(a.utmMedium,200), utmCampaign: clean(a.utmCampaign,200),
    utmContent: clean(a.utmContent,200), utmTerm: clean(a.utmTerm,200), referrer: clean(a.referrer,1000), landingPage: clean(a.landingPage,1000)
  };
} else if (type === 'community_profile_update') {
  const memberId = clean(body.memberId,120);
  const token = clean(body.profileUpdateToken,300);
  const rawPatch = body.patch && typeof body.patch === 'object' && !Array.isArray(body.patch) ? body.patch : {};
  const patch = {};
  for (const [k,v] of Object.entries(rawPatch)) {
    if (!allowedPatchKeys.has(k)) continue;
    if (k === 'selectedGoals') patch[k] = list(v, allowedGoals, 3);
    else if (k === 'status' && allowedStatus.has(clean(v,80))) patch[k] = clean(v,80);
    else if (k === 'studyField' && allowedStudy.has(clean(v,80))) patch[k] = clean(v,80);
    else if (k === 'experienceLevel' && allowedExperience.has(clean(v,80))) patch[k] = clean(v,80);
    else if (k === 'contributionAreas') patch[k] = list(v, allowedContribution, 2);
    else if (['studyFieldOther','university'].includes(k)) patch[k] = clean(v,300);
    else if (['linkedinUrl','githubUrl','portfolioUrl'].includes(k)) {
      const url = clean(v,1000); if (!url || /^https:\/\//i.test(url)) patch[k] = url;
    }
  }
  if (!memberId || !token || !Object.keys(patch).length) { valid = false; error = 'Missing member, token, or valid profile patch'; }
  normalized = { ...normalized, valid, error, memberId, profileUpdateToken: token, patch, updatedAt: now };
} else {
  valid = false; error = 'Unsupported request type'; normalized = { ...normalized, valid, error };
}
return [{json: normalized}];

